@startuml

class Scene {
  + code : string
  + description : string
}

class Setup {
  + code : string
  + photographicParameters : string
}

class Take {
  + takeNumber : int
  + filmMeters : float
  + reelCode : string
}

class Internal extends Scene {}

class External extends Scene {}

class DayScene extends External {}

class NightScene extends External {}

class Location {
  + code : string
  + address : string
  + description : string
}

Scene "1" *-- "1..*" Setup
Setup "1" *-- "1..*" Take
External "1" -- "1" Location

@enduml

